class SSHWorker(QThread):
    progress_updated = pyqtSignal(int)
    output_received = pyqtSignal(str)
    finished = pyqtSignal(bool, str)
    url_generated = pyqtSignal(str)

    def __init__(self, hostname, username, password, root_password):
        super().__init__()
        self.hostname = hostname
        self.username = username
        self.password = password
        self.root_password = root_password
        self.is_running = True
        self.detected_ip = ""

    def run(self):
        try:
            # Connect to server
            self.output_received.emit("⌛ Connecting to server...")
            ssh = paramiko.SSHClient()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh.connect(
                self.hostname,
                username=self.username,
                password=self.password,
                timeout=30
            )
            self.progress_updated.emit(5)

            # Create installation file
            self.output_received.emit("⚙️ Creating installation script...")
            script = self.generate_install_script()
            sftp = ssh.open_sftp()
            remote_path = "/tmp/ntp_install.sh"
            with sftp.file(remote_path, 'w') as remote_file:
                remote_file.write(script)
            sftp.chmod(remote_path, 0o755)  # Make executable
            sftp.close()
            self.progress_updated.emit(10)

            # Execute script as root
            self.output_received.emit("🚀 Starting installation (requires root privileges)...")
            command = f"echo '{self.root_password}' | sudo -S bash {remote_path}"
            self.progress_updated.emit(15)

            # Execute commands and monitor output
            channel = ssh.get_transport().open_session()
            channel.exec_command(command)
            self.monitor_ssh_channel(channel, ssh, remote_path)

        except Exception as e:
            self.output_received.emit(f"❌ Error: {str(e)}")
            self.finished.emit(False, str(e))

    def generate_install_script(self):
        return """#!/bin/bash

# --- NTP Server Installation Script ---

# 1. Basic updates
echo "Updating system..."
sudo apt update && sudo apt upgrade -y

# 2. Install Chrony (Modern NTP implementation)
echo "Installing Chrony..."
sudo apt install chrony -y

# 3. Configure Chrony to allow clients
echo "Configuring Chrony..."
# Backup original config
sudo cp /etc/chrony/chrony.conf /etc/chrony/chrony.conf.bak

# Append allow rule for all networks (0.0.0.0/0)
# You can restrict this later if needed
echo "allow 0.0.0.0/0" | sudo tee -a /etc/chrony/chrony.conf

# 4. Configure Firewall
echo "Configuring Firewall for port 123..."
if command -v ufw > /dev/null; then
    sudo ufw allow 123/udp
    sudo ufw reload
fi

# 5. Restart services
echo "Restarting NTP service..."
sudo systemctl restart chronyd
sudo systemctl enable chronyd

# 6. Get IP address
IP=$(hostname -I | awk '{print $1}')
echo "✅ NTP Server Installation Completed Successfully! Server IP: $IP"
"""

    def monitor_ssh_channel(self, channel, ssh, remote_path):
        output_buffer = ""
        while not channel.exit_status_ready() and self.is_running:
            time.sleep(0.5)
            if channel.recv_ready():
                data = channel.recv(1024).decode('utf-8')
                output_buffer += data
                self.output_received.emit(data)
                
                # Update progress based on output content for NTP installation
                if "apt update" in output_buffer:
                    self.progress_updated.emit(25)
                elif "install chrony" in output_buffer or "Installing Chrony" in output_buffer:
                    self.progress_updated.emit(50)
                elif "Configuring Chrony" in output_buffer:
                    self.progress_updated.emit(70)
                elif "ufw allow" in output_buffer or "Configuring Firewall" in output_buffer:
                    self.progress_updated.emit(85)
                elif "systemctl restart" in output_buffer:
                    self.progress_updated.emit(95)
                    
                # Detect IP in output (Using the echo message from script)
                ip_match = re.search(r'Server IP: (\d+\.\d+\.\d+\.\d+)', output_buffer)
                if ip_match:
                    self.detected_ip = ip_match.group(1)
                    
                # Detect errors
                if any(err in output_buffer.lower() for err in ["error", "fail"]):
                    self.output_received.emit("⚠️ Potential error detected!")
                    
                # Periodically clear buffer
                if len(output_buffer) > 10000:
                    output_buffer = output_buffer[-5000:]

        # Final cleanup
        ssh.exec_command(f"sudo rm -f {remote_path}")
        exit_status = channel.recv_exit_status()
        ssh.close()
        
        if exit_status == 0:
            if self.detected_ip:
                self.url_generated.emit(self.detected_ip)
            self.finished.emit(True, "Installation completed successfully!")
        else:
            self.finished.emit(False, f"Installation failed with exit code: {exit_status}")

    def stop(self):
        self.is_running = False

